// Lottery handoff: a shift's start numbers should equal the previous shift's end numbers (same terminal day).
const HANDOFF_F = [["online", "netSales", "Online lotto sales"], ["online", "pays", "Online lotto payouts"], ["scratch", "pays", "Scratch-off payouts"]];
async function addHandoff(env, S, date, rows, groups) {
  const lot = rows.filter(r => r.kind === "lottery");
  let prev = null;
  for (const g of groups) {
    const start = lot.find(r => r.stage === "start" && covers(r.shift).some(k => g.shifts.includes(k)));
    if (!start) continue;
    const first = g.shifts[0]; let pe;
    if (first > 1) pe = lot.filter(r => r.stage === "end" && covers(r.shift).includes(first - 1)).pop();
    else {
      if (!prev) prev = ((await env.DB.prepare("SELECT shift, stage, data FROM closes WHERE date = ? AND store = ? AND kind = 'lottery' ORDER BY created").bind(addDays(date, -1), S).all()).results || []).map(r => ({ ...r, data: JSON.parse(r.data) }));
      pe = prev.filter(r => r.stage === "end" && covers(r.shift).includes(3)).pop();
    }
    if (!pe) continue;
    const msgs = [];
    HANDOFF_F.forEach(([k, f, label]) => {
      const a = (pe.data || {})[k] || {}, b = (start.data || {})[k] || {};
      if (!a.forDate || a.forDate !== b.forDate) return;
      const va = num(a[f]), vb = num(b[f]); if (va === null || vb === null) return;
      if (Math.abs(va - vb) >= 0.01) msgs.push(label + ": " + usd2(vb) + " at this start vs " + usd2(va) + " at the last end");
    });
    if (msgs.length) g.handoff = msgs;
  }
}
// One status line per shift: red = needs you, amber = still to finish, green = all good.
const SHIFT_END_H = { 1: 6, 2: 14, 3: 22 };
function dayChecks(day, nowMs, tz) {
  const nowW = wallTime(nowMs, tz), base = Date.parse(day.date + "T00:00:00Z");
  return day.groups.map(g => {
    const endW = base + SHIFT_END_H[g.shifts[g.shifts.length - 1]] * 3600e3, ended = nowW >= endW, overdue = nowW >= endW + 3600e3;
    const vf = g.shifts.flatMap(k => day.cashiers[k] || []), lot = g.lottery.reports, hasEnd = lot.some(r => r.stage === "end");
    const bad = [], warn = [], who = x => x.cashier || ("Reg " + x.reg);
    g.lottery.checks.forEach(ch => { if (!ch.ok && !ch.missing) bad.push(ch.name.replace(" (SSCS)", "") + (ch.diff > 0 ? " over " : " short ") + usd2(Math.abs(ch.diff))); });
    vf.forEach(x => { if (x.overShort != null && Math.abs(x.overShort) >= day.flag) bad.push(who(x) + " register " + (x.overShort >= 0 ? "over " : "short ") + usd2(Math.abs(x.overShort))); });
    if (overdue && !hasEnd) bad.push("No lottery photos sent");
    else if (ended && !hasEnd) warn.push("Lottery photos not in yet");
    if (hasEnd && g.lottery.checks.some(ch => ch.key === "scratch" && ch.missing)) warn.push("Waiting for the SSCS count");
    vf.forEach(x => { if ((x.drops || 0) > 0 && x.counted == null) warn.push(who(x) + " safe drops not counted yet"); });
    (g.lottery.warns || []).forEach(w => warn.push(w));
    (g.handoff || []).forEach(w => bad.push("Lottery handoff gap: " + w));
    const items = bad.concat(warn);
    const level = bad.length ? "bad" : warn.length ? "warn" : (hasEnd || vf.length) ? "good" : "none";
    return { label: g.label, level, items, worked: (g.worked || []).map(w => w.staff) };
  });
}
