    let msg = "From: " + from + "\r\nTo: <" + m.to + ">\r\nSubject: " + mailHeader(m.subject || "Invoice") + "\r\nDate: " + new Date().toUTCString().replace("GMT", "+0000") +
      "\r\nMessage-ID: <" + rid(20) + "@closeout.workers.dev>\r\nMIME-Version: 1.0\r\nContent-Type: multipart/mixed; boundary=\"" + B + "\"\r\n\r\n" +
      "--" + B + "\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Transfer-Encoding: base64\r\n\r\n" + wrap76(b64utf8(m.text || "")) ;
    if (m.fileName) msg += "--" + B + "\r\nContent-Type: application/octet-stream; name=\"" + m.fileName + "\"\r\nContent-Disposition: attachment; filename=\"" + m.fileName + "\"\r\nContent-Transfer-Encoding: base64\r\n\r\n" + wrap76(b64utf8(m.fileText || ""));
    msg += "--" + B + "--\r\n.";
    await step(msg, ["250"]);
    try { await w.write(enc.encode("QUIT\r\n")); } catch {}
