  var ck=(PL.d.check||{})[m]||{};
  $("lck").innerHTML=PL_REP.map(function(x){return '<label class="ck'+(ck[x[0]]?" done":"")+'"><input type="checkbox" data-pck="'+x[0]+'"'+(ck[x[0]]?" checked":"")+'><span><b>'+esc(x[1])+'</b><br><span class="p">'+esc(x[2])+'</span><br><span class="mute" style="font-size:.84rem">'+esc(x[3])+'</span></span></label>'}).join("");
  var ms={};PL.d.entries.forEach(function(e){ms[e.month]=1});Object.keys(PL.d.gross).forEach(function(k){ms[k]=1});
