var CARD_RATES={"V":[1.95,0.17],"M":[1.95,0.17],"MF":[1.95,0.17],"AX":[2.80,0.17],"DS":[2.20,0.20],"DC":[2.40,0.15],"DB":[1.00,0.18],"EB":[1.00,0],"WX":[2.85,0.45],"VG":[2.85,0.45],"SA":[1.87,0.22]},CARD_RATE_DEFAULT=[1.95,0.17];
